import pandas as pd
import numpy as np
import json

df = pd.read_csv('/app/benchmark/data.csv')

def clean_condition(c):
    c = str(c).strip().lower()
    if c in ['new', 'nuevo', 'novo']:
        return 'New'
    elif c in ['used', 'usado']:
        return 'Used'
    elif 'refurbished' in c:
        return 'Refurbished'
    elif c in ['open box', 'caja abierta', 'new other']:
        return 'Open Box'
    else:
        return 'Other'

df['condition_clean'] = df['condition'].apply(clean_condition)
df_main = df[df['brand'].isin(['Apple', 'Garmin', 'Samsung'])].copy()

# Prepare chart data as JSON for embedding

# 1. Brand distribution
brand_dist = df_main['brand'].value_counts().to_dict()

# 2. Condition distribution
cond_dist = df_main['condition_clean'].value_counts().to_dict()

# 3. Country distribution (top 10)
country_dist = df_main['Country'].value_counts().head(10).to_dict()

# 4. Brand pricing stats
brand_pricing = {}
for brand in ['Apple', 'Garmin', 'Samsung']:
    bdf = df_main[df_main['brand']==brand]['price']
    brand_pricing[brand] = {
        'median': round(bdf.median(), 2),
        'mean': round(bdf.mean(), 2),
        'q1': round(bdf.quantile(0.25), 2),
        'q3': round(bdf.quantile(0.75), 2),
        'min': round(bdf.min(), 2),
        'max': round(bdf.max(), 2),
        'count': int(len(bdf))
    }

# 5. Geographic arbitrage data
geo_data = {}
for brand in ['Apple', 'Garmin', 'Samsung']:
    bdf = df_main[df_main['brand']==brand]
    country_counts = bdf['Country'].value_counts()
    valid = country_counts[country_counts >= 5].index
    cmed = bdf[bdf['Country'].isin(valid)].groupby('Country')['price'].median()
    global_median = bdf['price'].median()
    geo_data[brand] = {
        'global_median': round(global_median, 2),
        'countries': {c: {'median': round(v, 2), 'pct_diff': round((v - global_median)/global_median*100, 1)} for c, v in cmed.items()}
    }

# 6. Case size data
case_data = {}
for brand in ['Apple', 'Garmin', 'Samsung']:
    bdf = df_main[(df_main['brand']==brand) & df_main['Case_Size_mm'].notna()]
    if len(bdf) > 0:
        bdf = bdf.copy()
        bdf['size_cat'] = pd.cut(bdf['Case_Size_mm'], bins=[0, 40, 44, 48, 100], labels=['≤40mm', '41-44mm', '45-48mm', '49mm+'])
        size_prem = bdf.groupby('size_cat')['price'].agg(['median', 'mean', 'count'])
        case_data[brand] = {str(k): {'median': round(v['median'], 2), 'mean': round(v['mean'], 2), 'count': int(v['count'])} for k, v in size_prem.iterrows()}

# 7. Seller data
seller_counts = df_main['Seller_ID'].value_counts()
top_5_pct_count = max(1, int(len(seller_counts) * 0.05))
power_seller_ids = set(seller_counts.head(top_5_pct_count).index)
df_main['is_power_seller'] = df_main['Seller_ID'].isin(power_seller_ids)

seller_data = {
    'total_sellers': int(df_main['Seller_ID'].nunique()),
    'power_seller_count': int(len(power_seller_ids)),
    'power_seller_listings': int(df_main[df_main['is_power_seller']].shape[0]),
    'power_seller_pct': round(df_main[df_main['is_power_seller']].shape[0] / len(df_main) * 100, 1),
    'volume_distribution': {
        '1_listing': int((seller_counts == 1).sum()),
        '2_to_5': int(((seller_counts >= 2) & (seller_counts <= 5)).sum()),
        '6_to_20': int(((seller_counts >= 6) & (seller_counts <= 20)).sum()),
        '21_plus': int((seller_counts >= 21).sum())
    },
    'pricing_by_volume': {}
}

for brand in ['Apple', 'Garmin', 'Samsung']:
    bdf = df_main[df_main['brand']==brand]
    seller_data['pricing_by_volume'][brand] = {
        'power_median': round(bdf[bdf['is_power_seller']]['price'].median(), 2),
        'casual_median': round(bdf[~bdf['is_power_seller']]['price'].median(), 2),
        'power_mean': round(bdf[bdf['is_power_seller']]['price'].mean(), 2),
        'casual_mean': round(bdf[~bdf['is_power_seller']]['price'].mean(), 2)
    }

# Top 10 power sellers
top10_data = []
for sid, count in seller_counts.head(10).items():
    sdf = df_main[df_main['Seller_ID']==sid]
    brands = sdf['brand'].value_counts().to_dict()
    top10_data.append({
        'seller_id': sid,
        'listings': int(count),
        'median_price': round(sdf['price'].median(), 2),
        'mean_price': round(sdf['price'].mean(), 2),
        'brands': brands,
        'worldwide_pct': round(sdf['Is_Worldwide_Shipping'].mean() * 100, 0)
    })
seller_data['top10'] = top10_data

# 8. Condition premium
condition_data = {}
for brand in ['Apple', 'Garmin', 'Samsung']:
    bdf = df_main[df_main['brand']==brand]
    condition_data[brand] = {}
    for cond in ['New', 'Used', 'Open Box', 'Refurbished']:
        med = bdf[bdf['condition_clean']==cond]['price'].median()
        if pd.notna(med):
            condition_data[brand][cond] = round(med, 2)

# 9. Worldwide shipping
ww_data = {
    'power_sellers': round(df_main[df_main['is_power_seller']]['Is_Worldwide_Shipping'].mean() * 100, 1),
    'casual_sellers': round(df_main[~df_main['is_power_seller']]['Is_Worldwide_Shipping'].mean() * 100, 1)
}

# 10. Brand mix for power vs casual
brand_mix = {
    'power': df_main[df_main['is_power_seller']]['brand'].value_counts(normalize=True).to_dict(),
    'casual': df_main[~df_main['is_power_seller']]['brand'].value_counts(normalize=True).to_dict()
}

all_data = {
    'brand_dist': brand_dist,
    'cond_dist': cond_dist,
    'country_dist': country_dist,
    'brand_pricing': brand_pricing,
    'geo_data': geo_data,
    'case_data': case_data,
    'seller_data': seller_data,
    'condition_data': condition_data,
    'ww_data': ww_data,
    'brand_mix': brand_mix
}

with open('/tmp/report_data.json', 'w') as f:
    json.dump(all_data, f, indent=2)

print('Data exported to /tmp/report_data.json')
